<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --gold: #C9A84C;
    --gold-light: #F0D080;
    --gold-dark: #8B6914;
    --bg: #0F0F0F;
    --surface: #1A1A1A;
    --surface2: #252525;
    --surface3: #2E2E2E;
    --border: #333;
    --text: #E8E8E8;
    --text-dim: #999;
    --text-muted: #666;
    --red: #E05C5C;
    --green: #5CB85C;
    --blue: #4A9EDE;
    --purple: #9B7FD4;
    --orange: #E07B39;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Inter', 'Segoe UI', -apple-system, sans-serif;
