  .report-subtitle {
    font-size: 16px; color: var(--text-dim); max-width: 600px; margin-bottom: 24px;
  }
  .header-meta {
    display: flex; gap: 24px; flex-wrap: wrap;
    font-size: 12px; color: var(--text-muted);
  }
