  }
  .toc-title { font-size: 12px; letter-spacing: 2px; text-transform: uppercase; color: var(--gold); margin-bottom: 16px; font-weight: 600; }
  .toc-list { list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 8px 32px; }
  .toc-list li { font-size: 14px; }
  .toc-list a { color: var(--text-dim); }
  .toc-list a:hover { color: var(--gold-light); }
  .toc-num { color: var(--text-muted); margin-right: 8px; font-variant-numeric: tabular-nums; }

  /* KPI GRID */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin: 32px 0;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s;
  }
  .kpi-card:hover { border-color: var(--gold-dark); }
  .kpi-card::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0; height: 3px;
    background: linear-gradient(90deg, var(--gold), var(--gold-light));
  }
  .kpi-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); margin-bottom: 10px; }
  .kpi-value { font-size: 28px; font-weight: 700; color: var(--gold-light); line-height: 1; margin-bottom: 6px; }
  .kpi-sub { font-size: 12px; color: var(--text-muted); }
  .kpi-pos { color: var(--green); }
  .kpi-neg { color: var(--red); }

  /* CHART CONTAINERS */
  .chart-wrap {
    background: var(--surface);
