  }
  .chart-title {
    font-size: 14px; font-weight: 600; color: var(--text); margin-bottom: 4px;
  }
  .chart-caption { font-size: 12px; color: var(--text-muted); margin-bottom: 20px; }
  .chart-canvas-wrap { position: relative; }

  /* TWO-COL GRID */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 24px 0; }
