    font-variant-numeric: tabular-nums;
  }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: var(--surface2); }
  .data-table .pos { color: var(--green); }
  .data-table .neg { color: var(--red); }
  .data-table .neutral { color: var(--text); }
  .data-table .highlight-row td { background: var(--surface2); color: var(--text); }

  /* MILESTONE TIMELINE */
  .milestone-list { list-style: none; padding: 0; }
  .milestone-item {
    display: flex; align-items: flex-start; gap: 16px;
    padding: 16px 0;
    border-bottom: 1px solid var(--border);
  }
  .milestone-item:last-child { border-bottom: none; }
  .milestone-dot {
    width: 36px; height: 36px; border-radius: 50%;
    background: var(--surface2);
    border: 2px solid var(--gold-dark);
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    font-size: 12px; font-weight: 700; color: var(--gold);
  }
  .milestone-content { flex: 1; }
  .milestone-label { font-size: 14px; font-weight: 600; color: var(--text); margin-bottom: 2px; }
  .milestone-date { font-size: 12px; color: var(--text-muted); }

  /* REGIME LEGEND */
  .regime-legend { display: flex; gap: 20px; flex-wrap: wrap; margin-bottom: 16px; }
  .regime-item { display: flex; align-items: center; gap: 8px; font-size: 13px; }
  .regime-dot { width: 12px; height: 12px; border-radius: 2px; flex-shrink: 0; }

  /* INSIGHT BOXES */
  .insight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 24px 0; }
  .insight-box {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
  }
  .insight-box.warn { border-left: 3px solid var(--orange); }
  .insight-box.good { border-left: 3px solid var(--green); }
  .insight-box.info { border-left: 3px solid var(--blue); }
  .insight-box.alert { border-left: 3px solid var(--red); }
  .insight-title { font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 8px; }
  .insight-body { font-size: 13px; color: var(--text-dim); line-height: 1.5; }

  /* STAT GRID */
  .stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin: 24px 0; }
  .stat-box {
    background: var(--surface2);
    border-radius: 8px;
    padding: 16px;
    text-align: center;
  }
  .stat-val { font-size: 22px; font-weight: 700; color: var(--text); margin-bottom: 4px; }
  .stat-lbl { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); }

  /* BAR PILL */
  .bar-pill { display: flex; align-items: center; gap: 8px; }
  .bar-track { flex: 1; height: 6px; background: var(--surface3); border-radius: 3px; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 3px; background: var(--gold); transition: width 0.3s; }
  .bar-fill.neg { background: var(--red); }
  .bar-fill.pos { background: var(--green); }

  /* FOOTER */
  .report-footer {
    background: var(--surface);
    border-top: 1px solid var(--border);
    padding: 24px 40px;
    font-size: 12px; color: var(--text-muted);
    text-align: center;
  }
  .footnote { font-size: 11px; color: var(--text-muted); margin-top: 12px; font-style: italic; }

  /* SCROLLBAR */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: var(--surface); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .two-col, .three-col, .insight-grid { grid-template-columns: 1fr; }
    .stat-grid { grid-template-columns: repeat(2, 1fr); }
    .toc-list { grid-template-columns: 1fr; }
  }
  @media (max-width: 600px) {
    .kpi-grid { grid-template-columns: 1fr 1fr; }
    .report-title { font-size: 24px; }
    .container { padding: 0 20px; }
  }
</style>
</head>
