    </ul>
  </div>

  <!-- ===== KPIs ===== -->
  <div class="section" id="kpis">
    <div class="section-label">Summary Statistics</div>
    <h2 class="section-title">Key Performance Indicators</h2>
    <p class="section-desc">Full-period KPIs computed from 6,399 daily closing prices (Aug 2000 – Mar 2026). All figures derived exclusively from dataset values.</p>

